from typing import List, Tuple, Optional

def parse_range(header: str, size: int) -> Optional[List[Tuple[int, int]]]:
    if not header:
        return None

    # Split unit and range-set
    unit, range_str = header.split('=', 1)
    if unit.strip() != 'bytes':
        return None
    range_str = range_str.strip()
    if not range_str:
        return None

    specs = [s.strip() for s in range_str.split(',')]
    result = []

    for spec in specs:
        if not spec:
            continue
        parts = spec.split('-', 1)
        if len(parts) != 2:
            continue

        start_str, end_str = parts

        # Validate digit strings
        if start_str != '' and not start_str.isdigit():
            continue
        if end_str != '' and not end_str.isdigit():
            continue

        start = None
        if start_str != '':
            start = int(start_str)
            if start < 0:
                continue

        end = None
        if end_str != '':
            end = int(end_str)
            if end < 0:
                continue

        # Process based on presence of start and/or end
        if start is not None and end is not None:
            # Both present
            if start > end:
                continue
            if end >= size:
                end = size - 1
            if start >= size or start > end:
                continue
            result.append((start, end))

        elif start is not None:
            # Start only (e.g., "500-")
            if start >= size:
                continue
            result.append((start, size - 1))

        elif end is not None:
            # End only (suffix)
            suffix_len = end
            if suffix_len <= 0:
                continue
            start = max(0, size - suffix_len)
            if start >= size:
                continue
            result.append((start, size - 1))

        else:
            # Both empty (malformed)
            continue

    if not result:
        return None
    return result
```

