def wildcard_match(pattern, s):
    m = len(s)
    dp = [False] * (m + 1)
    dp[0] = True
    ndp = [False] * (m + 1)
    for ch in pattern:
        if ch == '*':
            ndp[0] = dp[0]
            for j in range(1, m + 1):
                ndp[j] = dp[j] or ndp[j-1]
        else:
            ndp[0] = False
            for j in range(1, m + 1):
                if ch == '?' or ch == s[j-1]:
                    ndp[j] = dp[j-1]
        dp, ndp = ndp, dp
    return dp[m]
