class RollbackDSU:
    def __init__(self, n: int):
        self.n = n
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []  # (small_root, old_size_small, old_size_large)

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> bool:
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            old_small = self.size[ra]
            old_large = self.size[rb]
            self.parent[ra] = rb
            self.size[rb] = old_large + old_small
            self.history.append((ra, old_small, old_large))
        else:
            old_small = self.size[rb]
            old_large = self.size[ra]
            self.parent[rb] = ra
            self.size[ra] = old_large + old_small
            self.history.append((rb, old_small, old_large))
        return True

    def snapshot(self) -> int:
        return len(self.history)

    def rollback(self, token: int) -> None:
        while len(self.history) > token:
            small, _, old_large = self.history.pop()
            self.parent[small] = small
            self.size[old_large] = old_large

    def components(self) -> int:
        return self.n - len(self.history)
