            if i == len(word):
                if node.word == word and node.count > 0:
                    node.count -= 1
                    return True
                return False

            ch = word[i]
            if ch not in node.children:
                return False

            found = helper(node.children[ch], i + 1)
            return found

        return helper(self._root, 0)

