def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]
    base = len(alphabet)
    sign = ''
    if n < 0:
        sign = '-'
        n = -n
    digits = []
    while n:
        digits.append(alphabet[n % base])
        n //= base
    return sign + ''.join(reversed(digits))


def from_base(s, alphabet):
    if not s:
        raise ValueError("empty string")
    base = len(alphabet)
    index = {ch: i for i, ch in enumerate(alphabet)}
    sign = 1
    if s[0] == '-':
        sign = -1
        s = s[1:]
    if not s:
        raise ValueError("empty string after sign")
    for ch in s:
        if ch not in index:
            raise ValueError(f"invalid character {ch}")
    value = 0
    for ch in s:
        value = value * base + index[ch]
    return sign * value
```

