import heapq

def topo_lex(graph):
    indegree = {}
    for u in graph:
        indegree[u] = 0
    for u, succs in graph.items():
        for v in succs:
            indegree[v] = indegree.get(v, 0) + 1

    heap = [node for node, deg in indegree.items() if deg == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in graph.get(u, []):
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(heap, v)

    if len(order) == len(indegree):
        return order
    return None
