function deepEqual(a, b, seen = new WeakMap()) {
    // Same reference
    if (a === b) return true;

    // Different types are never equal
    if (typeof a !== typeof b) return false;

    // NaN equals NaN
    if (typeof a === 'number' && typeof b === 'number') {
        if (Object.is(a, NaN) && Object.is(b, NaN)) return true;
        if (Object.is(a, 0) && Object.is(b, 0)) return true;
    }

    // Date compare by time value
    if (a instanceof Date) {
        return a.getTime() === b.getTime();
    }

    // RegExp compare by source and flags
    if (a instanceof RegExp) {
        return a.source === b.source && a.flags === b.flags;
    }

    // Map compare by contents
    if (a instanceof Map) {
        if (a.size !== b.size) return false;
        for (let [key, val] of a) {
            if (!b.has(key) || !deepEqual(val, b.get(key), seen)) return false;
        }
        return true;
    }

    // Set compare by contents
    if (a instanceof Set) {
        if (a.size !== b.size) return false;
        for (let val of a) {
            if (!b.has(val) || !deepEqual(val, val, seen)) return false;
        }
        return true;
    }

    // Arrays compare by index
    if (Array.isArray(a)) {
        if (a.length !== b.length) return false;
        for (let i = 0; i < a.length; i++) {
            if (!deepEqual(a[i], b[i], seen)) return false;
        }
        return true;
    }

    // Plain Objects compare by own enumerable keys (order independent)
    if (typeof a === 'object' && a !== null) {
        // Cycle detection
        if (seen.has(a)) return true;
        seen.set(a, true);

        const keysA = Reflect.ownKeys(a);
        const keysB = Reflect.ownKeys(b);

        if (keysA.length !== keysB.length) return false;
        const keysBSet = new Set(keysB);
        for (let key of keysA) {
            if (!keysBSet.has(key)) return false;
        }

        for (let key of keysA) {
            if (!deepEqual(a[key], b[key], seen)) return false;
        }
        return true;
    }

    return false;
}

module.exports = deepEqual;
