const pLimit = (n) => {
    const queue = [];
    let runningCount = 0;

    const next = () => {
        if (runningCount < n && queue.length > 0) {
            const { fn, resolve, reject } = queue.shift();
            runningCount++;

            // Execute the provided function
            const resultPromise = fn();

            resultPromise.then(
                (value) => {
                    resolve(value);
                    runningCount--;
                    next();
                },
                (error) => {
                    reject(error);
                    runningCount--;
                    next();
                }
            );
        }
    };

    return (fn) => {
        return new Promise((resolve, reject) => {
            queue.push({ fn, resolve, reject });
            next();
        });
    };
};

module.exports = pLimit;
