    let current = doc;

    for (let i = 0; i < tokens.length - 1; i++) {
      const token = tokens[i];
      const decodedToken = token.replace(/~1/g, '/').replace(/~0/g, '~');

      // Handle undefined or null root for traversal purposes
      if (current === undefined || current === null) {
        if (i > 0) {
          current = {};
        } else {
          return doc;
        }
      }

      if (typeof current === 'object') {
        if (current[decodedToken] === undefined) {
          current[decodedToken] = {};
        }
        current = current[decodedToken];
      } else {
        // Cannot traverse into primitive values
        break;
      }
    }

    const lastToken = tokens[tokens.length - 1];
    const decodedLastToken = lastToken.replace(/~1/g, '/').replace(/~0/g, '~');

    if (Array.isArray(current) && decodedLastToken === '-') {
      current.push(value);
    } else {
      current[decodedLastToken] = value;
