class Emitter {
  constructor() {
    this._listeners = new Map();
    this._emitDepth = 0;
    this._lastError = null;
  }

  on(event, fn) {
    if (!this._listeners.has(event)) {
      this._listeners.set(event, []);
    }
    const listeners = this._listeners.get(event);
    listeners.push({ fn, addedAtEmit: this._emitDepth, type: 'normal' });
    return () => this.off(event, fn);
  }

  once(event, fn) {
    const wrapper = (...args) => {
      this.off(event, wrapper);
      fn(...args);
    };
    return this.on(event, wrapper);
  }

  off(event, fn) {
    const listeners = this._listeners.get(event);
    if (!listeners) return;
    const filtered = listeners.filter((item) => item.fn !== fn);
    if (filtered.length !== listeners.length) {
      this._listeners.set(event, filtered);
    }
  }

  emit(event, ...args) {
    const currentDepth = this._emitDepth++;
    const listeners = this._listeners.get(event) || [];
    // Snapshot listeners added before the current depth
    const toProcess = listeners.filter((item) => item.addedAtEmit < currentDepth);
    let invokedCount = 0;
    let error = null;

    try {
      for (const item of toProcess) {
        // Check if listener still exists in master list (handles removals)
        const index = listeners.indexOf(item);
        if (index === -1) {
          continue;
        }

        if (item.type === 'once') {
          // Remove before running
          listeners.splice(index, 1);
        }

        const func = item.fn;
        try {
          func(...args);
          invokedCount++;
        } catch (e) {
          if (!error) {
            error = e;
          }
        }
      }
    } finally {
      this._emitDepth--;
      if (error) throw error;
    }

    return invokedCount;
  }
}

module.exports = Emitter;
