module.exports = function singleFlight(loader) {
    const pending = new Map();
    let inflight = 0;

    const load = function(key) {
        const flight = pending.get(key);
        if (flight) {
            return flight.promise;
        }

        let resolve, reject;
        const promise = new Promise((res, rej) => {
            resolve = res;
            reject = rej;
        });

        const current = {
            promise: promise,
            resolve: resolve,
            reject: reject
        };

        pending.set(key, current);
        inflight++;

        loader(key)
            .then((value) => {
                // Resolve only once
                current.resolve(value);
                // Drop entry so later calls re-run the loader
                pending.delete(key);
            })
            .catch((error) => {
                // Reject all waiters, do not cache the error state
                current.reject(error);
                pending.delete(key);
            })
            .finally(() => {
                inflight--;
            });

        return promise;
    };

    Object.defineProperty(load, 'inflight', {
        get: () => inflight,
        set: (val) => { inflight = val; }
    });

    return load;
};
