module.exports = function sqlTag(strings, ...values) {
  let resultText = strings[0];
  const resultValues = [];
  let paramIndex = 1;

  const processValue = (value) => {
    // Case: Array
    if (Array.isArray(value)) {
      resultText += '(';
      for (let i = 0; i < value.length; i++) {
        if (i > 0) resultText += ', ';
        processValue(value[i]);
      }
      resultText += ')';
    }
    // Case: Result of sqlTag (Object with text/values)
    else if (value && typeof value === 'object' && 'text' in value && 'values' in value) {
      // Inline text, renumbering placeholders ($1 -> $newIndex)
      const placeholderRegex = /\$(\d+)/g;
      resultText += value.text.replace(placeholderRegex, (match, capturedNumber) => {
        const innerNumber = parseInt(capturedNumber, 10);
        const newNumber = paramIndex + innerNumber - 1;
        paramIndex = newNumber + 1; // Increment for the *last* placeholder in this inline block
        return `$${newNumber}`;
      });

      // Merge values recursively
      if (Array.isArray(value.values)) {
        value.values.forEach(processValue);
      }
    }
    // Case: Primitive
    else {
      resultText += `$${paramIndex}`;
      resultValues.push(value);
      paramIndex++;
    }
  };

  for (let i = 0; i < values.length; i++) {
    resultText += strings[i];
    processValue(values[i]);
  }
  resultText += strings[values.length];

  return { text: resultText, values: resultValues };
};
