function observe(target, onChange, path = []) {
    const handler = {
        get(target, prop, receiver) {
            const value = Reflect.get(target, prop, receiver);

            // Return plain value for primitives (null, string, number, boolean, symbol)
            if (value === null || typeof value !== 'object') {
                return value;
            }

            // Wrap plain objects and arrays in a Proxy
            // We check for plain objects and arrays to ignore built-ins like Date, Map, RegExp
            if (isPlainObject(value) || Array.isArray(value)) {
                return observe(value, onChange, [...path, prop]);
            }

            return value;
        },

        set(target, prop, value, receiver) {
            const currentPath = [...path, prop];
            const oldValue = target[prop];

            // If the value is the same (SameValueZero), do nothing (no event)
            if (Object.is(oldValue, value)) {
                return true;
            }

            // Call onChange with path, newValue, and oldValue
            onChange(currentPath, value, oldValue);

            // Perform the write operation
            Reflect.set(target, prop, value, receiver);
            return true;
        },

        deleteProperty(target, prop) {
            const currentPath = [...path, prop];
            const oldValue = target[prop];

            // Report deletion, new value is undefined
            onChange(currentPath, undefined, oldValue);

            // Perform deletion
            Reflect.deleteProperty(target, prop);
            return true;
        }
    };

    return new Proxy(target, handler);
}

module.exports = observe;
