function memoize(fn, keyFn) {
    let cache = new Map();
    let calls = 0;

    const wrapper = function(...args) {
        calls++;
        let key;

        if (keyFn) {
            key = keyFn(...args);
        } else {
            const arg = args[0];
            if (arg !== null && typeof arg === 'object') {
                if (!(cache instanceof WeakMap)) {
                    cache = new WeakMap();
                }
                key = arg;
            } else {
                key = args[0];
            }
        }

        if (cache.has(key)) {
            return cache.get(key);
        }

        try {
            const result = fn(...args);
            cache.set(key, result);
            return result;
        } catch (e) {
            throw e;
        }
    };

    wrapper.cache = cache;
    wrapper.calls = calls;
    wrapper.clear = function() {
        cache = new Map();
        calls = 0;
    };

    return wrapper;
}

module.exports = memoize;
