function* zipLongest(fill, ...iterables) {
    // If there are no iterables, return immediately (yield nothing).
    if (iterables.length === 0) return;

    const iterators = iterables.map(it => it[Symbol.iterator]());
    // Initialize state by pulling one item from each iterator.
    // This is necessary to detect empty iterables and determine the start state.
    const states = iterators.map(it => it.next());

    let active = true;

    while (active) {
        const row = [];
        let lives = 0;

        for (let i = 0; i < iterators.length; i++) {
            const { value, done } = states[i];

            if (done) {
                // Input is exhausted, use fill value.
                row.push(fill);
            } else {
                // Pull the next item from the live input.
                states[i] = iterators[i].next();
                if (states[i].done) {
                    // Input finished *during* this step, use fill for this row.
                    row.push(fill);
                } else {
                    // Input is still live, push the value.
                    row.push(value);
                    lives++;
                }
            }
        }

        // If no inputs were live this iteration, all are exhausted.
        if (lives === 0) {
            active = false;
        }

        yield row;
    }
}

module.exports = zipLongest;
```

