  if (typeof qs !== 'string') return {};
  qs = qs.split('?').pop();
  if (!qs) return {};

  var result = {};

  function traverse(obj, segments, value) {
    var i, segment, isArray, target;
    for (i = 0; i < segments.length - 1; i++) {
      segment = segments[i];
      target = obj[segment];

      isArray = !isNaN(Number(segment));
      if (!target) {
        if (isArray) obj[segment] = [];
        else obj[segment] = {};
        target = obj[segment];
      } else if (isArray && !Array.isArray(target)) {
        target = obj[segment] = [target];
      } else if (!isArray && Array.isArray(target)) {
        // If we have an array and try to access a string key, convert array to object
        obj[segment] = {};
        target = obj[segment];
      }
      obj = target;
    }

    // Last segment
    segment = segments[i]; // i = segments.length - 1
    isArray = !isNaN(Number(segment));
    if (isArray) segment = Number(segment);
    target = obj[segment];

    // Collision handling at the leaf
    if (target === undefined) {
      obj[segment] = value;
    } else if (isArray && Array.isArray(target)) {
      // If accessing array index with index, check size and set
      if (segment < target.length) {
         target[segment] = value;
      } else {
         // push if we assume sequential filling, or just extend with undefined
         // Standard behavior for append is push, but here we fill holes.
         target[segment] = value; 
      }
    } else if (isArray && !Array.isArray(target)) {
      // Index on object -> convert object to array
      obj[segment] = [target, value];
    } else if (!isArray && Array.isArray(target)) {
      // String key on array -> object
      obj[segment] = value;
    } else {
      // String key on object (collision)
      // If previous value was scalar, turn into array? "repeated bare key becomes an array"
      if (target !== undefined && (typeof target === 'string' || typeof target === 'number')) {
         obj[segment] = [target, value];
      } else {
         obj[segment] = value;
      }
    }
  }

  qs.split('&').forEach(function(pair) {
    if (!pair) return;
    var eqIdx = pair.indexOf('=');
    var key = (eqIdx >= 0) ? pair.slice(0, eqIdx) : pair;
    var val = (eqIdx >= 0) ? pair.slice(eqIdx + 1) : '';

    try {
      val = decodeURIComponent(val.replace(/\+/g, ' '));
    } catch (e) {
      val = val; 
    }

    // Parse key path
    var segments = [];
    var keyParts = key.split('[');
    for (var k = 0; k < keyParts.length; k++) {
      var part = keyParts[k];
      if (!part) continue;
      var closingIdx = part.indexOf(']');
      var seg = part;
      if (closingIdx !== -1) {
        seg = part.slice(0, closingIdx);
      }
      if (seg) segments.push(seg);
    }

    traverse(result, segments, val);
  });

  return result;
};

var buildQuery = function(obj) {
  if (!obj || typeof obj !== 'object') return '';

  var result = [];
  var keys = Object.keys(obj).sort();

  function recurse(current, prefix) {
    for (var i = 0; i < keys.length; i++) {
      var key = keys[i];
      var val = obj[key];
      var isLast = (i === keys.length - 1);
      var fullKey = prefix ? prefix + '[' + key + ']' : key;

      if (val === null || val === undefined) continue;

      if (typeof val === 'object') {
        // Nested object or array
        recurse(val, fullKey);
      } else {
        // Scalar value
        result.push(fullKey + '=' + encodeURIComponent(val));
      }
    }
  }

  recurse(obj, '');
  return result.join('&');
};

module.exports = {
  parseQuery: parseQuery,
  buildQuery: buildQuery
};
