module.exports = function createStore(reducer, initialState) {
  let state = initialState;
  const listeners = [];
  let isDispatchingReducer = false;

  function getState() {
    return state;
  }

  function notify(action) {
    const snapshot = listeners.slice();
    let isDispatchingReducer = true;
    try {
      state = reducer(state, action);
    } finally {
      isDispatchingReducer = false;
    }
    for (const listener of snapshot) {
      listener(state);
    }
  }

  function dispatch(action) {
    if (isDispatchingReducer) {
      throw new Error('Dispatching while dispatching');
    }
    notify(action);
  }

  return {
    getState,
    subscribe(fn) {
      listeners.push(fn);
      const unsubscribe = () => {
        const index = listeners.indexOf(fn);
        if (index !== -1) {
          listeners.splice(index, 1);
        }
      };
      return unsubscribe;
    },
    dispatch
  };
};
