module.exports = function toposortTasks(tasks) {
    const names = Object.keys(tasks);
    const adj = {};
    const indeg = {};
    const missingDeps = [];

    names.forEach(n => {
        adj[n] = [];
        indeg[n] = tasks[n].deps.length;
        tasks[n].deps.forEach(dep => {
            if (tasks[dep]) {
                adj[dep].push(n);
            } else {
                missingDeps.push(dep);
            }
        });
    });

    if (missingDeps.length) {
        return Promise.reject(new Error(`missing name: ${missingDeps.join(', ')}`));
    }

    const visited = new Set();
    const visiting = new Set();
    let hasCycle = false;

    function dfs(node) {
        if (hasCycle) return;
        visiting.add(node);
        visited.add(node);

        const children = adj[node] || [];
        for (const child of children) {
            if (!visited.has(child)) {
                dfs(child);
            } else if (visiting.has(child)) {
                hasCycle = true;
                return;
            }
        }
        visiting.delete(node);
    }

    names.forEach(n => {
        if (!visited.has(n)) {
            dfs(n);
        }
    });

    if (hasCycle) {
        return Promise.reject(new Error('cycle'));
    }

    const results = {};
    let globalError = null;
    let currentLevel = names.filter(n => indeg[n] === 0);

    while (currentLevel.length > 0) {
        const promises = currentLevel.map(name => {
            return new Promise(resolve => {
                const deps = tasks[name].deps;
                const depValues = {};
                let error = null;

                for (const dep of deps) {
                    const val = results[dep];
                    if (val instanceof Error) {
                        error = val;
                    } else if (val === undefined) {
                        resolve(new Error(`missing name: ${dep}`));
                        return;
                    } else {
                        depValues[dep] = val;
                    }
                }

                if (error) {
                    resolve(error);
                    return;
                }

                tasks[name].run(depValues)
                    .then(resolve)
                    .catch(err => {
                        if (!globalError) globalError = err;
                        resolve(err);
                    });
            });
        });

        Promise.allSettled(promises).then(settled => {
            const nextLevel = [];
            settled.forEach((res, idx) => {
                const name = currentLevel[idx];
                if (res.status === 'fulfilled') {
                    results[name] = res.value;
                } else {
                    const err = res.reason;
                    results[name] = err;
                    if (!globalError) globalError = err;
                }

                adj[name].forEach(child => {
                    indeg[child]--;
                    if (indeg[child] === 0) {
                        nextLevel.push(child);
                    }
                });
            });
            currentLevel = nextLevel;
        });
    }

    return new Promise((resolve, reject) => {
        if (globalError) {
            reject(globalError);
        } else {
            resolve(results);
        }
    });
};
