export class Bus<E extends Record<string, unknown>> {
    private listeners: Record<string, Array<(payload: unknown) => void>> = {};

    on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
        if (!this.listeners[k]) {
            this.listeners[k] = [];
        }

        const listeners = this.listeners[k];
        listeners.push(fn);

        return () => {
            const index = listeners.indexOf(fn);
            if (index > -1) {
                listeners.splice(index, 1);
            }
        };
    }

    emit<K extends keyof E>(k: K, payload: E[K]): void;
    emit<K extends keyof E>(k: K): void;
    emit<K extends keyof E>(k: K, payload?: unknown) {
        const handlers = this.listeners[k];
        if (handlers) {
            handlers.forEach(h => h(payload));
        }
    }
}
