type DiscriminantKeys<U, K extends keyof U> = U extends { [P in K]: infer V } ? V : never;

type VariantType<U, K extends keyof U, V> = Extract<U, { [k in K]: V }>;

type MatchHandlers<U, K extends keyof U> = {
    [Key in DiscriminantKeys<U, K>]: (v: VariantType<U, K, Key>) => any;
};

export function match<U, K extends keyof U>(
    value: U,
    handlers: MatchHandlers<U, K>
): ReturnType<MatchHandlers<U, K>> {
    if (value.kind in handlers) {
        return handlers[value.kind](value as any);
    }

    const exhaustiveCheck: never = value;
    throw new Error(`Unhandled variant: ${(exhaustiveCheck as { kind: string }).kind}`);
}
