export class Builder<Config> {
    private data: Partial<Config> = {} as Partial<Config>;
    private built = false;

    set(key: keyof Config, value: Config[keyof Config]): void {
        (this.data as Record<string, unknown>)[key] = value;
    }

    build(): Config {
        if (this.built) {
            throw new Error("Builder has already been built");
        }
        this.built = true;
        // TypeScript enforces that all required keys are present here.
        // If 'data' is missing a required key, it will fail the assignment check.
        return this.data as Config;
    }
}

export function builder<Config>(): Builder<Config> {
    return new Builder<Config>();
}
