export type DeepAwaited<T> = T extends Promise<infer U> ? DeepAwaited<U> : T extends object ? { [K in keyof T]: DeepAwaited } : T;

export async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
    if (typeof value === 'function') {
        return value as DeepAwaited<T>;
    }

    if (Array.isArray(value)) {
        return Promise.all(value.map(item => deepAwait(item))) as Promise<DeepAwaited<T>>;
    }

    if (value && typeof value === 'object') {
        return Object.fromEntries(
            Object.entries(value).map(([key, nested]) => [key, await deepAwait(nested)])
        ) as DeepAwaited<T>;
    }

    return value as DeepAwaited<T>;
}
