export type Curry<F extends (...args: any[]) => any> = F extends (...args: infer Args) => infer R
  ? Args extends []
    ? F
    : Args extends [infer A, ...infer Rest]
      ? <X extends A>(arg: X) => Curry<(...args: Rest) => R>
      : never
    : never;

export function curry<F extends (...args: any[]) => any>(f: F): Curry<F> {
  const arityZero = () => f();
  if (Parameters<F>.length === 0) {
    return arityZero as Curry<F>;
  }

  return <X extends Parameters<F>[0]>(arg: X) => {
    return curry((...rest: Parameters<F>) => f(arg, ...rest));
  } as Curry<F>;
}
