export type Email = Brand<string, 'Email'>;

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function isEmail(s: string): s is Email {
    return (s as any).__brand === 'Email';
}

export function asEmail(s: string): Email {
    if (!emailRegex.test(s)) {
        throw new Error("Invalid email address");
    }
    // Wrap the string primitive into a mutable String instance
    const strObj = Object(s);
    // Attach the brand property
    return Object.assign(strObj, { __brand: 'Email' as const });
}
