type Sep = '-' | '_';
type _Sep = Sep;

type Letter = 'a' | 'b' | 'c' | 'd' | 'e' | 'f' | 'g' | 'h' | 'i' | 'j' | 'k' | 'l' | 'm' | 'n' | 'o' | 'p' | 'q' | 'r' | 's' | 't' | 'u' | 'v' | 'w' | 'x' | 'y' | 'z';

type CamelCase<S extends string> = 
  // Drop leading separators
  S extends `-${infer T}` | `_${infer T}`
    ? CamelCase<T>
    : // Match: Separators + Letter (Start of new word)
    S extends `${_Sep}${Letter}{${infer Rest}}`
      ? `${Capitalize<Letter>}${CamelCase<Rest>}`
      : // Match: Letter + Separators + Letter (Boundary between words)
    S extends `${Letter}${_Sep}${Letter}{${infer Rest}}`
      ? `${Capitalize<Letter>}${CamelCase<Rest>}`
      : // Match: Letter sequence (Word)
    S extends `${Letter}${${Letter}*}`
      ? S
      : S;

type SnakeCase<S extends string> = 
  // Drop leading separators
  S extends `-${infer T}` | `_${infer T}`
    ? SnakeCase<T>
    : // Match: Word + Word (End of first word)
    S extends `${Letter}${${Letter}*}${${Letter}${${Letter}*}}`
      ? `${S extends `${infer W1}${W2}` ? `${W1}_${Uppercase<Extract<W2, `${Letter}${string}`>}` : S}${SnakeCase<Extract<S, `${W2}${string}`> | ''>}`
      : S extends `${Letter}${${Letter}*}${_Sep}${Letter}{${infer Rest}}`
        // Match: Word + Separator + Letter (End of first word)
        ? `${S extends `${infer W1}${_Sep}${W2}` ? `${W1}_${Uppercase<Extract<W2, `${Letter}${string}`>}` : S}${SnakeCase<Extract<S, `${W2}${string}`> | ''>}`
        : // Match: Letter sequence (Word)
        S extends `${Letter}${${Letter}*}`
          ? S
          : S;

type CamelKeys<T extends object> = {
  [K in keyof T as CamelCase<string>]: T[K];
};
