type Ok<T, E> = { readonly type: 'ok'; readonly value: T };
type Err<T, E> = { readonly type: 'err'; readonly error: E };
type Result<T, E> = Ok<T, E> | Err<T, E>;

function ok<T, E>(value: T): Result<T, E> {
  return { type: 'ok', value };
}

function err<T, E>(error: E): Result<T, E> {
  return { type: 'err', error };
}

function isOk<T, E>(r: Result<T, E>): r is Ok<T, E> {
  return r.type === 'ok';
}

function isErr<T, E>(r: Result<T, E>): r is Err<T, E> {
  return r.type === 'err';
}

function map<T, E, U>(r: Result<T, E>, f: (v: T) => U): Result<U, E> {
  if (isOk(r)) {
    return ok(f(r.value));
  }
  return r;
}

function unwrapOr<T>(r: Result<T, any>, value: T): T {
  if (isOk(r)) {
    return r.value;
  }
  return value;
}

export { type Result, ok, err, isOk, isErr, map, unwrapOr };
