const paramRegex = /:(\w+)/g;

export function defineRoutes<Routes extends Record<string, string>>(routes: Routes) {
  type RouteFn = (params: { [P in keyof P & string]: string }) => string;

  return Object.fromEntries(
    Object.entries(routes).map(([name, template]) => {
      const paramNames: string[] = [];
      let match: RegExpExecArray | null;

      while ((match = paramRegex.exec(template)) !== null) {
        paramNames.push(match[1]);
      }

      const paramArgs = paramNames.join(', ');

      const builder = new Function('params', `
        const ${paramArgs} = params;
        return template.replace(/:(\\\\w+)/g, (_, key) => ${paramArgs}[key]);
      `);

      return [name, builder] as [string, RouteFn];
    })
  ) as {
    [K in keyof Routes]: (params: { [P in keyof P & string]: string }) => string;
  };
}
