export type DeepPartial = {
    [P in keyof T]?: T[P] extends object ? DeepPartial : T[P];
};

export const applyPatch = <T>(base: T, patch: DeepPartial): T => {
    if (patch === undefined) return base;

    const isObject = typeof base === 'object' && base !== null;
    const result: any = isObject ? (Array.isArray(base) ? [] : {}) : base;

    for (const key in patch) {
        // patch[key] is accessed via any to bypass strict checks for optional properties
        const pVal = (patch as any)[key];
        const bVal = (base as any)[key];

        if (pVal === undefined) continue;

        if (
            typeof pVal === 'object' &&
            pVal !== null &&
            typeof bVal === 'object' &&
            bVal !== null
        ) {
            if (Array.isArray(pVal)) {
                result[key] = pVal; // Replace array wholesale
            } else {
                result[key] = applyPatch(bVal, pVal); // Recursively merge objects
            }
        } else {
            result[key] = pVal; // Primitive override
        }
    }

    return result as T;
};
